import { useCallback, useEffect, useState } from 'react';
import { fetchEvalRun, fetchEvalRuns, fetchFixtures, fetchFights } from '../services/api';
import { latestPerVersion } from '../types/EvalRun';
import type { EvalReport, EvalRunSummary, FixtureSummary } from '../types/EvalRun';
import type { Fight } from '../types/Fight';
import { useWindowWidth } from '../hooks/useWindowWidth';
import ClassificationBreakdown from '../components/accuracy/ClassificationBreakdown';
import ConfusionHeatmap from '../components/accuracy/ConfusionHeatmap';
import FixtureTable from '../components/accuracy/FixtureTable';
import Glossary from '../components/accuracy/Glossary';
import HeadlineF1 from '../components/accuracy/HeadlineF1';
import NotMeasurable from '../components/accuracy/NotMeasurable';
import OffsetDotStrip from '../components/accuracy/OffsetDotStrip';
import ProvenanceLine from '../components/accuracy/ProvenanceLine';
import RoundsCheck from '../components/accuracy/RoundsCheck';
import StateDumbbell from '../components/accuracy/StateDumbbell';
import VersionTrendChart from '../components/accuracy/VersionTrendChart';
import WorstList from '../components/accuracy/WorstList';

/**
 * Training Lab, Section E only ("Pipeline accuracy") — see
 * ~/.claude/plans/i-have-now-reference-radiant-salamander.md. Sections
 * A-D/F/G of the full design need labelled-data volume/infrastructure this
 * app doesn't have yet; this page covers only what the current fixtures
 * (a labelled reference fight scored against a re-uploaded, AI-processed
 * copy of itself) can honestly show — E0/E1/E2/E8.
 */
export default function PipelineAccuracy() {
  const width = useWindowWidth();
  const isMobile = width < 640;

  const [fixtures, setFixtures] = useState<FixtureSummary[]>([]);
  const [fights, setFights] = useState<Fight[]>([]);
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [runs, setRuns] = useState<EvalRunSummary[]>([]);
  /** `id` of the version being drilled into below the trend chart — not
   * necessarily the latest one; defaults to latest but the user can pick an
   * earlier version (including v1) via VersionTrendChart. */
  const [selectedRunId, setSelectedRunId] = useState<number | null>(null);
  const [report, setReport] = useState<EvalReport | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadFixtures = useCallback(() => {
    setLoading(true);
    Promise.all([fetchFixtures(), fetchFights()])
      .then(([fx, fl]) => {
        setFixtures(fx);
        setFights(fl);
        setSelectedId((prev) => {
          if (prev !== null && fx.some((f) => f.reference_fight_id === prev)) return prev;
          const measurable = fx.find((f) => f.is_measurable);
          return (measurable ?? fx[0])?.reference_fight_id ?? null;
        });
      })
      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => { loadFixtures(); }, [loadFixtures]);

  const selected = fixtures.find((f) => f.reference_fight_id === selectedId) ?? null;

  useEffect(() => {
    if (!selected || !selected.is_measurable) {
      setRuns([]);
      setReport(null);
      return;
    }
    // Switching fixtures should default back to that fixture's latest
    // version, not carry over whatever version id was selected before.
    setSelectedRunId(null);
    fetchEvalRuns(selected.reference_fight_id)
      .then(setRuns)
      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'));
  }, [selected]);

  const versions = latestPerVersion(runs);
  const selectedIndex = selectedRunId === null
    ? versions.length - 1
    : versions.findIndex((v) => v.id === selectedRunId);
  const current = selectedIndex >= 0 ? versions[selectedIndex] : null;
  const previous = current && selectedIndex > 0 ? versions[selectedIndex - 1] : null;
  const currentRunId = current?.id ?? null;

  useEffect(() => {
    if (currentRunId === null) {
      setReport(null);
      return;
    }
    fetchEvalRun(currentRunId)
      .then((r) => setReport(r.report))
      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'));
  }, [currentRunId]);

  const candidates = fights.filter((f) => f.purpose === 'ai_labeled' && f.state === 'completed');

  return (
    <div style={{ maxWidth: 1440, margin: '0 auto', padding: isMobile ? '14px 13px 60px' : '22px 30px 80px', width: '100%' }}>
      <div style={{ marginBottom: 16 }}>
        <h1 className="font-display" style={{ fontSize: isMobile ? 30 : 40, lineHeight: 0.94, margin: 0, color: 'var(--text-primary)' }}>
          PIPELINE ACCURACY
        </h1>
        <p style={{ margin: '5px 0 0', fontSize: 12.5, fontWeight: 600, color: 'var(--text-muted)' }}>
          Reference fixtures scored against pipeline predictions, across versions
        </p>
      </div>

      {loading && <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Loading…</div>}
      {error && <div style={{ fontSize: 13, color: 'var(--red-500)', marginBottom: 14 }}>{error}</div>}

      {!loading && fixtures.length === 0 && (
        <div className="glass" style={{ padding: '20px 22px', fontSize: 13, color: 'var(--text-muted)' }}>
          No labelled reference fixture exists yet. Upload a fight as "Self-annotate → Reference" and
          finish labelling it to create one.
        </div>
      )}

      {fixtures.length > 0 && (
        <div className="glass" style={{ padding: '20px 22px 22px', marginBottom: 16 }}>
          <div className="label" style={{ marginBottom: 12 }}>Fixtures</div>
          <FixtureTable fixtures={fixtures} selectedId={selectedId} onSelect={setSelectedId} />
          <Glossary />
        </div>
      )}

      {selected && (
        <div className="glass" style={{ padding: '20px 22px 22px' }}>
          {!selected.is_measurable ? (
            <NotMeasurable fixture={selected} candidates={candidates} onScored={loadFixtures} />
          ) : current ? (
            <>
              <div style={{ marginBottom: 16 }}>
                <ProvenanceLine run={current} />
              </div>
              <div style={{ marginBottom: 20 }}>
                <HeadlineF1 current={current} previous={previous} />
              </div>
              <div style={{ marginBottom: 20 }}>
                <div className="label" style={{ marginBottom: 11 }}>Accuracy history — this fixture, every pipeline version</div>
                <VersionTrendChart versions={versions} selectedId={current.id} onSelect={setSelectedRunId} />
              </div>

              {report && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 20, paddingTop: 18, borderTop: '1px solid rgba(255,255,255,0.05)' }}>
                  <div>
                    <div className="label" style={{ marginBottom: 11 }}>Classification — matched strikes only</div>
                    <ClassificationBreakdown strikes={report.strikes} />
                  </div>

                  <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr', gap: 20 }}>
                    <div>
                      <div className="label" style={{ marginBottom: 11 }}>Strike family confusion</div>
                      <ConfusionHeatmap confusion={report.strikes.family_confusion} emptyLabel="No specific-family matches yet." />
                    </div>
                    <div>
                      <div className="label" style={{ marginBottom: 11 }}>Timing</div>
                      <OffsetDotStrip offsets={report.strikes.matched_offsets} />
                    </div>
                  </div>

                  <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr', gap: 20 }}>
                    <div>
                      <div className="label" style={{ marginBottom: 11 }}>Fight state</div>
                      <StateDumbbell state={report.state} />
                      <div style={{ marginTop: 12 }}>
                        <ConfusionHeatmap confusion={report.state.confusion} emptyLabel="No state frames scored yet." />
                      </div>
                    </div>
                    <div>
                      <div className="label" style={{ marginBottom: 11 }}>Rounds</div>
                      <RoundsCheck rounds={report.rounds} />
                    </div>
                  </div>

                  <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr', gap: 20 }}>
                    <WorstList title="Worst misses" fps={report.fps} items={report.strikes.missed} emptyLabel="No missed strikes." />
                    <WorstList title="Worst false positives" fps={report.fps} items={report.strikes.spurious} emptyLabel="No false positives." />
                  </div>
                </div>
              )}
            </>
          ) : (
            <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Loading runs…</div>
          )}
        </div>
      )}
    </div>
  );
}

import asyncio
import json
import os
import re
from pathlib import Path
from typing import List, Optional

from fastapi import APIRouter, File, Form, HTTPException, Request, UploadFile
from fastapi.responses import FileResponse, Response, StreamingResponse

from app.models.fight import FIGHT_PURPOSES, FightResponse
from app.models.fighter_frame import FighterFrameResponse
from app.models.fight_event import FightEventCreate, FightEventResponse, FightEventUpdate
from app.models.round import RoundResponse
from app.services import (
    event_service,
    fight_service,
    fighter_frame_service,
    fighter_service,
    round_service,
)
from app.services.pipeline_runner import extract_video_meta, run_validation_async, terminate_pipeline
from app.utils.fight_state_listener import register_queue, unregister_queue

router = APIRouter()


_VIDEO_BASE_DIR = Path(os.getenv("VIDEO_BASE_DIR", ""))
_KEEP_VIDEO_ON_DELETE = os.getenv("KEEP_VIDEO_ON_DELETE", "").lower() in ("1", "true", "yes")


def _resolve_video_path(stored_path: str) -> Path:
    p = Path(stored_path)
    return p if p.is_absolute() else (_VIDEO_BASE_DIR / p).resolve()


_ALLOWED_EXTENSIONS = {".mp4", ".mkv", ".mov"}
_UPLOAD_CHUNK_SIZE = 1024 * 1024  # 1 MB


def _sanitize_filename(name: str) -> str:
    stem = Path(name).stem
    suffix = Path(name).suffix.lower()
    safe = re.sub(r"[^\w\-.]", "_", stem).strip("_") or "video"
    return safe + suffix


def _unique_path(directory: Path, filename: str) -> Path:
    dest = directory / filename
    if not dest.exists():
        return dest
    stem = Path(filename).stem
    suffix = Path(filename).suffix
    counter = 2
    while True:
        dest = directory / f"{stem}_{counter}{suffix}"
        if not dest.exists():
            return dest
        counter += 1


@router.get("/", response_model=List[FightResponse])
def get_fights():
    return fight_service.get_all_fights()


@router.get("/stream")
async def stream_fight_state(request: Request):
    async def event_generator():
        q: asyncio.Queue = asyncio.Queue()
        register_queue(q)
        try:
            snapshot = await asyncio.to_thread(fight_service.get_all_fights)
            data = json.dumps([
                {"id": f.id, "state": f.state} for f in snapshot
            ])
            yield f"event: snapshot\ndata: {data}\n\n"

            while True:
                if await request.is_disconnected():
                    break
                try:
                    payload = await asyncio.wait_for(q.get(), timeout=15.0)
                    yield f"data: {payload}\n\n"
                except asyncio.TimeoutError:
                    yield ": ping\n\n"
        finally:
            unregister_queue(q)

    return StreamingResponse(
        event_generator(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
        },
    )


@router.post("/upload", response_model=FightResponse, status_code=201)
async def upload_fight(
    file: UploadFile = File(...),
    red_fighter_id: Optional[int] = Form(None),
    blue_fighter_id: Optional[int] = Form(None),
    purpose: str = Form(...),
):
    if purpose not in FIGHT_PURPOSES:
        raise HTTPException(
            status_code=400,
            detail=f"purpose must be one of {', '.join(FIGHT_PURPOSES)}",
        )

    ext = Path(file.filename or "").suffix.lower()
    if ext not in _ALLOWED_EXTENSIONS:
        raise HTTPException(
            status_code=400,
            detail=f"Unsupported file type '{ext}'. Allowed: {', '.join(sorted(_ALLOWED_EXTENSIONS))}",
        )

    if (
        red_fighter_id is not None
        and blue_fighter_id is not None
        and red_fighter_id == blue_fighter_id
    ):
        raise HTTPException(
            status_code=400,
            detail="Red and blue corners cannot be the same fighter",
        )

    for fid in (red_fighter_id, blue_fighter_id):
        if fid is not None and fighter_service.get_fighter_by_id(fid) is None:
            raise HTTPException(status_code=404, detail=f"Fighter {fid} not found")

    fight_videos_dir = _VIDEO_BASE_DIR / "fight_videos"
    fight_videos_dir.mkdir(parents=True, exist_ok=True)

    safe_name = _sanitize_filename(file.filename or "video.mp4")
    dest = _unique_path(fight_videos_dir, safe_name)
    tmp_dest = dest.with_name(f".{dest.name}.part")

    try:
        with open(tmp_dest, "wb") as f:
            while chunk := await file.read(_UPLOAD_CHUNK_SIZE):
                f.write(chunk)
            f.flush()
            os.fsync(f.fileno())
        tmp_dest.rename(dest)
    except Exception:
        tmp_dest.unlink(missing_ok=True)
        if dest.exists():
            dest.unlink()
        raise

    relative_path = f"fight_videos/{dest.name}"

    try:
        fps, width, height = extract_video_meta(relative_path)
    except Exception:
        dest.unlink(missing_ok=True)
        raise HTTPException(status_code=400, detail="Could not read video metadata")

    try:
        fight = fight_service.create_fight(
            video_path=relative_path,
            fps=fps,
            width=width,
            height=height,
            red_fighter_id=red_fighter_id,
            blue_fighter_id=blue_fighter_id,
            purpose=purpose,
        )
    except Exception as e:
        dest.unlink(missing_ok=True)
        if "unique" in str(e).lower() or "duplicate" in str(e).lower():
            raise HTTPException(status_code=409, detail="A fight with this video already exists")
        raise

    # Only the AI track runs strike detection and the state machine; both
    # labelling purposes get the reduced pipeline that stops at keypoints.
    pid = run_validation_async(
        relative_path, fight.id, skip_events=(purpose != "ai_labeled")
    )
    fight_service.set_fight_pid(fight.id, pid)

    return fight


@router.get("/{fight_id}/rounds/", response_model=List[RoundResponse])
def get_rounds(fight_id: int):
    return round_service.get_rounds(fight_id)


@router.get("/{fight_id}/frames/", response_model=List[FighterFrameResponse])
def get_fighter_frames(fight_id: int):
    return fighter_frame_service.get_fighter_frames(fight_id)


@router.get("/{fight_id}/events/", response_model=List[FightEventResponse])
def get_fight_events(
    fight_id: int,
    fighter_id: Optional[int] = None,
    action: Optional[str] = None,
    success: Optional[bool] = None,
    kind: Optional[str] = None,
    source: Optional[str] = None,
):
    return event_service.get_events_by_fight(fight_id, fighter_id, action, success, kind, source)


@router.post("/{fight_id}/events/", response_model=FightEventResponse, status_code=201)
def create_fight_event(fight_id: int, payload: FightEventCreate):
    fight = fight_service.get_fight_by_id(fight_id)
    if fight is None:
        raise HTTPException(status_code=404, detail="Fight not found")
    return event_service.create_event(fight_id, payload)


@router.put("/{fight_id}/events/{event_id}", response_model=FightEventResponse)
def update_fight_event(fight_id: int, event_id: int, payload: FightEventUpdate):
    event = event_service.update_event(fight_id, event_id, payload)
    if event is None:
        raise HTTPException(status_code=404, detail="Event not found")
    return event


@router.delete("/{fight_id}/events/{event_id}", status_code=204)
def delete_fight_event(fight_id: int, event_id: int):
    deleted = event_service.delete_event(fight_id, event_id)
    if not deleted:
        raise HTTPException(status_code=404, detail="Event not found")
    return Response(status_code=204)


@router.post("/{fight_id}/finish-labeling", response_model=FightResponse)
def finish_labeling(fight_id: int):
    try:
        fight = fight_service.finish_labeling(fight_id)
    except fight_service.NotFullyAnnotated as e:
        raise HTTPException(status_code=409, detail=str(e))
    if fight is None:
        raise HTTPException(
            status_code=409,
            detail="Fight is not currently in labeling_in_progress state",
        )
    return fight


@router.get("/{fight_id}/video")
def get_fight_video(fight_id: int):
    fight = fight_service.get_fight_by_id(fight_id)
    if fight is None:
        raise HTTPException(status_code=404, detail="Fight not found")
    video_path = _resolve_video_path(fight.video_path)
    if not video_path.exists():
        raise HTTPException(status_code=404, detail="Video file not found")
    return FileResponse(str(video_path), media_type="video/mp4")


@router.delete("/{fight_id}", status_code=204)
def delete_fight(fight_id: int):
    pid = fight_service.get_fight_pid(fight_id)
    if pid is not None:
        terminate_pipeline(pid)

    video_path = fight_service.delete_fight(fight_id)
    if video_path is None:
        raise HTTPException(status_code=404, detail="Fight not found")
    if not _KEEP_VIDEO_ON_DELETE:
        resolved = _resolve_video_path(video_path)
        if resolved.exists():
            resolved.unlink()
    return Response(status_code=204)

from typing import List, Optional

from app.utils.db import run_db_query
from app.models.fight_event import FightEvent, FightEventCreate, FightEventUpdate
from app.models.round import Round


def get_events_by_fight(
    fight_id: int,
    fighter_id: Optional[int] = None,
    action: Optional[str] = None,
    success: Optional[bool] = None,
    kind: Optional[str] = None,
    source: Optional[str] = None,
) -> List[FightEvent]:
    def _query(session):
        if source == "label" and (kind is None or kind == "round"):
            _ensure_round_events_seeded(session, fight_id)

        q = session.query(FightEvent).filter(FightEvent.fight_id == fight_id)
        if fighter_id is not None:
            q = q.filter(FightEvent.fighter_id == fighter_id)
        if action:
            q = q.filter(FightEvent.action.ilike(f"{action}%"))
        if success is not None:
            q = q.filter(FightEvent.success.is_(success))
        if kind is not None:
            q = q.filter(FightEvent.kind == kind)
        if source is not None:
            q = q.filter(FightEvent.source == source)
        return q.order_by(FightEvent.frame).all()

    return run_db_query(_query)


def _ensure_round_events_seeded(session, fight_id: int) -> None:
    """Human-verified round bounds are seeded from AI segmentation the first
    time a fight's hand labels are fetched, so the labeller starts from a
    pre-filled boundary instead of marking every round from scratch. Must
    only ever run for a source='label' fetch — an ai_labeled fight's Player
    fetch (source='prediction') must never trigger this."""
    has_round_events = (
        session.query(FightEvent)
        .filter(
            FightEvent.fight_id == fight_id,
            FightEvent.source == "label",
            FightEvent.kind == "round",
        )
        .first()
    ) is not None
    if has_round_events:
        return

    rounds = (
        session.query(Round)
        .filter(Round.fight_id == fight_id)
        .order_by(Round.round_number)
        .all()
    )
    for r in rounds:
        session.add(FightEvent(
            fight_id=fight_id,
            source="label",
            kind="round",
            frame=r.start_frame,
            end_frame=r.end_frame,
            value=str(r.round_number),
        ))
    if rounds:
        session.commit()


def create_event(fight_id: int, payload: FightEventCreate) -> FightEvent:
    def _query(session):
        event = FightEvent(
            fight_id=fight_id,
            source="label",
            kind=payload.kind,
            frame=payload.frame,
            end_frame=payload.end_frame,
            description=payload.description,
            corner=payload.corner,
            action=payload.action,
            target=payload.target,
            success=payload.success,
            value=payload.value,
            labeler=payload.labeler,
        )
        session.add(event)
        session.commit()
        session.refresh(event)
        return event

    return run_db_query(_query)


def update_event(fight_id: int, event_id: int, payload: FightEventUpdate) -> Optional[FightEvent]:
    def _query(session):
        event = (
            session.query(FightEvent)
            .filter(
                FightEvent.id == event_id,
                FightEvent.fight_id == fight_id,
                FightEvent.source == "label",
                FightEvent.kind != "point",
            )
            .first()
        )
        if event is None:
            return None
        if payload.frame is not None:
            event.frame = payload.frame
        if payload.end_frame is not None:
            event.end_frame = payload.end_frame
        if payload.value is not None:
            event.value = payload.value
        session.commit()
        session.refresh(event)
        return event

    return run_db_query(_query)


def delete_event(fight_id: int, event_id: int) -> bool:
    def _query(session):
        # source='label' is the single most important guard in this
        # service: it makes it impossible for the Annotate delete endpoint
        # to ever remove a pipeline-predicted row.
        deleted = (
            session.query(FightEvent)
            .filter(
                FightEvent.id == event_id,
                FightEvent.fight_id == fight_id,
                FightEvent.source == "label",
            )
            .delete()
        )
        session.commit()
        return deleted > 0

    return run_db_query(_query)


def rounds_fully_annotated(fight_id: int, session=None) -> bool:
    """Every detected round has a (possibly labeller-adjusted) `round`-kind
    label event — the precondition finish-labeling gates on."""
    def _query(s):
        round_count = s.query(Round).filter(Round.fight_id == fight_id).count()
        event_count = (
            s.query(FightEvent)
            .filter(
                FightEvent.fight_id == fight_id,
                FightEvent.source == "label",
                FightEvent.kind == "round",
            )
            .count()
        )
        return round_count > 0 and event_count >= round_count

    if session is not None:
        return _query(session)
    return run_db_query(_query)

