:root {
  font-family: 'Manrope', system-ui, sans-serif;
  line-height: 1.5;
  font-weight: 400;
  color-scheme: dark;
  color: #f1f5f9;
  background-color: #050709;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  /* ── Brand design tokens ─────────────────────────── */
  --bg-base: #050709;
  --surface-glass: rgba(255,255,255,0.04);
  --surface-inner: rgba(0,0,0,0.30);
  --header-bg: rgba(5,7,9,0.72);
  --text-primary: #f1f5f9;
  --text-secondary: #cbd5e1;
  --text-tertiary: #94a3b8;
  --text-muted: #64748b;
  --text-disabled: #475569;
  --cyan-400: #00daf3;
  --cyan-600: #0099b0;
  --cyan-on: #001f24;
  --purple-600: #7c3aed;
  --orange-400: #ff7043;
  --orange-600: #e64a19;
  --green-500: #a3c900;
  --red-500: #ef4444;
  --slate-400: #94a3b8;
  --f-red: #ff4d4d;
  --f-red-dim: rgba(255,77,77,0.16);
  --f-blue: #3aa0ff;
  --f-blue-dim: rgba(58,160,255,0.16);
  --border-glass: rgba(255,255,255,0.07);
  --border-subtle: rgba(255,255,255,0.05);
  --border-cyan: rgba(0,218,243,0.18);
  --accent: #00daf3;
  --accent-2: #0099b0;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  min-height: 100vh;
}

body {
  min-width: 320px;
}

#root {
  width: 100%;
}

h1, h2, h3, h4, h5, h6 {
  margin: 0;
}

a {
  font-weight: 500;
  color: #00daf3;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  outline: none;
  transition: opacity 0.15s, transform 0.15s, box-shadow 0.15s, background 0.15s;
}

button:active {
  transform: scale(0.97);
}

/* Corner-select cards: state change (border/bg/glow) must be instant, no scale/transform. */
.fighter-corner-btn,
.fighter-corner-btn:active {
  transition: none;
  transform: none;
}

button:focus-visible {
  outline: 2px solid rgba(0, 218, 243, 0.6);
  outline-offset: 2px;
}

.material-symbols-outlined {
  font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24;
  user-select: none;
}

/* ── Display font ──────────────────────────────────── */

.font-display {
  font-family: 'Bebas Neue', sans-serif;
  letter-spacing: 0.02em;
}

/* ── Entry animations ──────────────────────────────── */

@keyframes fade-up {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}

.anim-fade-up {
  animation: fade-up 0.5s ease-out both;
}

.anim-delay-1 { animation-delay: 0.08s; }
.anim-delay-2 { animation-delay: 0.18s; }
.anim-delay-3 { animation-delay: 0.28s; }

/* ── Video overlay animations ──────────────────────── */

@keyframes video-feedback {
  0%   { opacity: 0.9;  transform: translate(-50%, -50%) scale(0.8); }
  30%  { opacity: 0.9;  transform: translate(-50%, -50%) scale(1.15); }
  100% { opacity: 0;    transform: translate(-50%, -50%) scale(1.45); }
}

@keyframes seek-pulse {
  0%, 100% { opacity: 0.9;  transform: translate(-50%, -50%) scale(1); }
  50%       { opacity: 0.9;  transform: translate(-50%, -50%) scale(1.18); }
}

@keyframes seek-fade {
  from { opacity: 0.9;  transform: translate(-50%, -50%) scale(1); }
  to   { opacity: 0;    transform: translate(-50%, -50%) scale(1.35); }
}

/* ── Background orb animations ─────────────────────── */

@keyframes orb-drift-a {
  0%, 100% { transform: translate(0, 0) scale(1); }
  50%       { transform: translate(40px, 60px) scale(1.08); }
}

@keyframes orb-drift-b {
  0%, 100% { transform: translate(0, 0) scale(1); }
  50%       { transform: translate(-50px, -40px) scale(1.05); }
}

@keyframes orb-drift-c {
  0%, 100% { transform: translate(0, 0) scale(1); }
  50%       { transform: translate(30px, -50px) scale(1.06); }
}

/* ── Grain texture ──────────────────────────────────── */

@keyframes grain-shift {
  0%, 100% { transform: translate(0, 0); }
  10%       { transform: translate(-2%, -3%); }
  30%       { transform: translate(3%, 2%); }
  50%       { transform: translate(-1%, 3%); }
  70%       { transform: translate(2%, -2%); }
  90%       { transform: translate(-3%, 1%); }
}

.grain-overlay {
  position: fixed;
  inset: -50%;
  width: 200%;
  height: 200%;
  opacity: 0.032;
  pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  background-size: 200px 200px;
  animation: grain-shift 0.5s steps(1) infinite;
  z-index: 2;
}

/* ── Hover states ───────────────────────────────────── */

.btn-glass {
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 8px;
  color: #94a3b8;
  display: flex;
  align-items: center;
  justify-content: center;
}

.btn-glass:hover {
  background: rgba(255,255,255,0.1);
  color: #e2e8f0;
}

.btn-primary:hover {
  box-shadow: 0 0 24px rgba(0,218,243,0.4);
}

.nav-link:hover {
  color: #94a3b8 !important;
  background: rgba(255,255,255,0.04) !important;
}

.event-item:hover {
  background: rgba(255,255,255,0.03) !important;
}

/* ── Glass surfaces & helper classes ───────────────── */

.glass {
  background: var(--surface-glass);
  backdrop-filter: blur(20px) saturate(160%);
  -webkit-backdrop-filter: blur(20px) saturate(160%);
  border: 1px solid var(--border-glass);
  border-radius: 16px;
}

.inner-tile {
  background: var(--surface-inner);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
}

.divider {
  height: 1px;
  background: rgba(255,255,255,0.05);
  border: none;
  margin: 0;
}

.label {
  font-size: 10.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: rgba(255,255,255,0.28);
}

.pill {
  font-size: 11.5px;
  font-weight: 700;
  padding: 6px 13px;
  border-radius: 7px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-disabled);
  cursor: pointer;
}

.pill.active {
  background: color-mix(in srgb, var(--accent) 15%, transparent);
  color: var(--accent);
  border-color: color-mix(in srgb, var(--accent) 25%, transparent);
  box-shadow: 0 0 12px color-mix(in srgb, var(--accent) 12%, transparent);
}

/* ── Feed animations ────────────────────────────────── */

@keyframes feed-in {
  from { transform: translateY(9px); opacity: 0; }
  to   { transform: translateY(0);   opacity: 1; }
}

@keyframes pulse-ring {
  0%   { box-shadow: 0 0 0 0 color-mix(in srgb, var(--accent) 45%, transparent); }
  70%  { box-shadow: 0 0 0 8px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}

@keyframes scope-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: 0.4; transform: scale(0.7); }
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

/* ── Scrollbar ──────────────────────────────────────── */

::-webkit-scrollbar { width: 5px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 10px; }
::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.2); }

/* ── Annotate screen ────────────────────────────────── */

.kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border-radius: 6px;
  background: rgba(255,255,255,0.07);
  border: 1px solid var(--border-glass);
  border-bottom-width: 2px;
  font-size: 11px;
  font-weight: 800;
  color: var(--text-secondary);
  font-family: 'Manrope', sans-serif;
  letter-spacing: 0.02em;
  flex-shrink: 0;
}

.punch-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 6px;
  border: 1px solid;
  font-size: 12px;
  font-weight: 800;
  font-family: 'Manrope', sans-serif;
  flex-shrink: 0;
}

.tl-scroll::-webkit-scrollbar { height: 10px; }
.tl-scroll::-webkit-scrollbar-track { background: rgba(255,255,255,0.03); }
.tl-scroll::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.16);
  border-radius: 6px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
.tl-scroll::-webkit-scrollbar-thumb:hover {
  background: rgba(255,255,255,0.28);
  background-clip: padding-box;
}

.tl-clip { padding: 0; transition: transform .1s; }
.tl-clip:hover { transform: translateY(-1px) scale(1.08); }
.tl-ruler:hover { background: rgba(255,255,255,0.025); }

.icon-btn {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: rgba(255,255,255,0.04);
  border: 1px solid var(--border-glass);
  color: var(--text-tertiary);
  cursor: pointer;
