1	export type Status = 'good' | 'warning' | 'critical' | 'unverified' | 'none' | 'circular';
2	
3	/**
4	 * Icon + text always paired, never colour alone — good/critical collapse for
5	 * red-green colourblindness, and critical's red is close to the red corner.
6	 * `good`/`warning` use their own hex rather than the app's `--green-500`/
7	 * `--red-500` tokens: those are already claimed by other meanings
8	 * (training_data purpose, round spans) — see memory "frontend-palette-collisions".
9	 */
10	const STATUS: Record<Status, { color: string; icon: string }> = {
11	  good: { color: '#0ca30c', icon: 'check_circle' },
12	  warning: { color: '#fab219', icon: 'warning' },
13	  critical: { color: 'var(--red-500)', icon: 'error' },
14	  unverified: { color: 'var(--text-muted)', icon: 'help' },
