      <aside style={{ display: 'flex', flexDirection: 'column', gap: 12, minWidth: 0 }}>
        <div className="glass" style={{ padding: '16px 18px 18px' }}>
          <div className="label" style={{ marginBottom: 8 }}>Event</div>
