  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    const seek = () => {
      video.currentTime = windowStart;
      video.playbackRate = speed;
      setCurrentTime(windowStart);
      video.play().catch(() => {});
      setIsPlaying(true);
